window.products.push({"id":428238,"name":"3-Pair Tall Boot Storage Holder & Shape Maintainer and Dry Rack Shoe Stand, Black by Madison Home Products","category":"homeandappliances","retail price":22.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81sgfT1zp2L._AC_SL1500_.jpg","description":"Reduce the clutter in your closet, mudroom, garage, or wherever you keep your shoes Ever wonder why your boots seem to fade after a short period of time? A boot rack not only keeps your closet space organized, but helps reduce wear and tear by keeping your boots upright, and shaped to their true form. This freestanding boot organizer holds up to 3 pairs of tall boots, preserving its material, preventing unnecessary creasing and cracking. Fast and Easy Assembly. Instructions included. Approximate Dimensions (in inches): Overall - 23.75 H x 11.5 D x 17.75 W Each Boot Holder - 18.0 H","images":["https://m.media-amazon.com/images/I/81sgfT1zp2L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"MADISON HOME PRODUCTS","source_asin":"B09XFJGSBD","category_path":"Home & Kitchen"},"sku":"BM-428238","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B09XFJGSBD","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B09XFJGSBD","price_pending":true,"merchant_ready":false});
