window.products.push({"id":428302,"name":"Malden International Designs Weathered Sentiments Wood with Antique Gold Metal Family Plaque Picture Frame, 4x6, Brown","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/91h6JVMmLfL._AC_SL1500_.jpg","description":"Transform the look of your home or office with this classic picture frame. Sentiments can express your feelings and/or memories and with this photo frame, you can share it with everyone! With its simple yet distressed design, it can be combined with other frames for a unique look. This item comes individually boxed which makes it perfect for a gift. For three generations Malden International Designs has been a family owned business, starting out in a small brick mill building in Malden Massachusetts. Since that time, they have grown into a leader of tabletop frames, wall frames and photo albums.","images":["https://m.media-amazon.com/images/I/91h6JVMmLfL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Malden","source_asin":"B00N1SE2TS","category_path":"Home & Kitchen"},"sku":"BM-428302","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00N1SE2TS","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00N1SE2TS","price_pending":true,"merchant_ready":false});
window.products.push({"id":428303,"name":"PRUNING SEAL 13OZ","category":"homeandappliances","retail price":20.2,"sale price":null,"image":"https://m.media-amazon.com/images/I/41c+5RSqcGL._AC_.jpg","description":"Spectracide Pruning Seal, 13 oz. A flexible sealant with multiple outdoor uses. Helps protect trees and smaller plants from diseases that can enter through pruned areas. This product also effectively seals and waterproofs clay pots, wooden planters, rain gutters, roof flashings and small sections of asphalt driveways. Can also be used to coat the underside of a lawn mower deck to protect from debris damage.","images":["https://m.media-amazon.com/images/I/41c+5RSqcGL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Spectracide","source_asin":"B01EQIHQLM","category_path":"Home & Kitchen"},"sku":"BM-428303","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01EQIHQLM","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01EQIHQLM","price_pending":true,"merchant_ready":false});
